contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr, uint minVal) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        c.SetMinSum(minVal); if (__ESBMC_reverted()) return;
        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && c.MinSum() == beforeMin && address(c).balance == beforeBal);
    }

    receive() external payable {}
}

